  <main class="workspace">
    <div id="activity-message" class="activity-message" role="status" aria-live="polite" aria-atomic="true"><span class="activity-rune" aria-hidden="true">&#9670;</span><div><strong id="status-title">Ready to create</strong><span id="status-detail">Choose a quest or start from a template.</span></div><button id="dismiss-status" class="status-dismiss" aria-label="Dismiss message">&times;</button></div>

    <section id="stage-author" class="journey-stage active" data-stage-panel="author">
      <header class="stage-hero"><div><span class="eyebrow">Stage 1 &middot; Author</span><h2>Shape the quest one beat at a time</h2><p>Choose actions a player can understand immediately. Studio handles the Runtime plumbing.</p></div><button id="author-next" class="continue-button">Rehearse quest <span aria-hidden="true">&rarr;</span></button></header>
      <section class="project-strip panel">
