            <section class="inspector-section"><h3>Player action</h3><label>Common action<select id="beat-kind"></select></label><p id="beat-instruction" class="instruction"></p><div id="beat-specific" class="specific-fields"></div><label id="beat-wait-row" hidden>Wait for seconds<input id="beat-wait" type="number" min="1" max="300"></label></section>
            <section class="inspector-section"><h3>Completion</h3><div id="beat-repeat-row"><label>Complete this action<input id="beat-repeat" type="number" min="1" max="16" value="1"><small>time(s), up to 16</small></label><label id="beat-window-row" hidden>Within seconds <small>(optional)</small><input id="beat-window" type="number" min="1" max="86400" placeholder="No time limit"></label></div></section>
            <section class="inspector-section afterward-section"><div class="section-title"><div><h3>Afterward</h3><span class="muted">Only add what the player should notice.</span></div></div><label>Show a message<textarea id="beat-message" maxlength="500" placeholder="Optional player feedback"></textarea></label><div id="beat-effect-list" class="beat-effect-list"></div><div class="effect-adder"><label>Add another response<select id="beat-effect-type"></select></label><button id="beat-add-effect" class="quiet">Add</button></div><div id="beat-reward" class="reward-card"><span class="eyebrow">Quest reward</span><label>Item<select id="beat-reward-item"><option value="">No reward</option><option>Wood</option><option>Stone</option><option>Resin</option><option>Coins</option></select></label><label>Quantity<input id="beat-reward-quantity" type="number" min="1" max="100" value="1"></label></div></section>
            <div class="button-row beat-actions"><button id="beat-earlier" class="quiet">Move up</button><button id="beat-later" class="quiet">Move down</button><button id="beat-duplicate" class="quiet">Duplicate</button><button id="beat-remove" class="danger">Remove</button></div>
          </div>
