      <div class="picker-toolbar"><label class="picker-search"><span class="sr-only">Search player actions</span><input id="event-search" type="search" autocomplete="off" placeholder="Search actions, instructions, or schools"></label><label class="extended-toggle"><input id="include-extended" type="checkbox"> Include Extended events</label></div>
      <div id="event-categories" class="event-categories" role="toolbar" aria-label="Filter by rune school"></div>
      <div class="picker-body"><div id="event-results" class="event-results" role="list" aria-label="Player actions"></div><aside id="event-preview" class="event-preview" aria-live="polite"><span class="eyebrow">Action details</span><h3>Choose an action</h3><p>Production actions can become quest beats. Research actions stay visible so the boundary is explicit.</p></aside></div>
      <p id="event-result-count" class="picker-count" aria-live="polite"></p>
