    <section id="stage-rehearse" class="journey-stage" data-stage-panel="rehearse" hidden>
      <header class="stage-hero"><div><span class="eyebrow">Stage 2 &middot; Rehearse</span><h2>Walk through the quest before opening the game</h2><p>Preview the same trigger logic Runtime uses and catch confusing beats early.</p></div><button id="rehearse-next" class="continue-button">Publish &amp; play <span aria-hidden="true">&rarr;</span></button></header>
      <div class="rehearsal-layout">
