      <nav class="tool-switcher" aria-label="Advanced tools"><button data-tool-tab="settings" class="active">Project settings</button><button data-tool-tab="graph">Graph editor</button><button data-tool-tab="json">Certified JSON</button><button data-tool-tab="data">Data &amp; history</button></nav>
      <section id="tool-settings" class="tool-panel panel">
