.app-actions{position:relative;z-index:55;display:flex;align-items:center;justify-content:flex-end;gap:14px;margin-left:auto;min-width:255px}.save-state{margin:0}.tools-menu{position:relative}.tools-menu summary,.library-actions summary,.manual-rehearsal summary{cursor:pointer;list-style:none;font-weight:750}.tools-menu summary::-webkit-details-marker,.library-actions summary::-webkit-details-marker,.manual-rehearsal summary::-webkit-details-marker{display:none}.tools-menu>summary{padding:9px 12px;border:1px solid #465151;border-radius:9px;background:#1a2225;color:#d8d5ca}.tools-menu[open]>summary{border-color:#7a673c;color:var(--gold)}.tools-popover{position:absolute;right:0;top:47px;z-index:80;width:210px;padding:7px;background:#11181a;border:1px solid #4a5554;border-radius:11px;box-shadow:var(--shadow)}.tools-popover button{display:block;width:100%;text-align:left;background:transparent;color:var(--ink)}.tools-popover button:hover{background:#252c29}
