.library{padding:16px;overflow:hidden}.library h2{margin:2px 0 0;font:750 22px Georgia,serif}.project-list{flex:1;margin:14px -5px;min-height:120px}.project-button{border-radius:9px;padding:11px}.project-button.active{background:linear-gradient(145deg,#2b2d23,#1d2420);border-color:#76643c}.new-project{margin-top:10px;padding-top:14px;border-top:1px solid var(--line)}.new-project label{margin:0;color:var(--muted);font-size:11px}.library-actions{display:block;margin-top:12px}.library-actions>summary{padding:8px 0;color:var(--muted);font-size:12px}.library-actions>summary:before,.manual-rehearsal>summary:before{content:'+ ';color:var(--gold)}.library-actions[open]>summary:before,.manual-rehearsal[open]>summary:before{content:'- '}.library-actions>div{display:grid;gap:7px}.library-actions button{width:100%}.library-hint{margin:14px 0 0;color:#7f8b87;font-size:11px}
