function renderCanvas(){if(!project)return;let map=Object.fromEntries(project.nodes.map(n=>[n.id,n])),paths=[];for(let n of project.nodes)for(let i=0;i<(n.routes||[]).length;i++){let r=n.routes[i],to=map[r.destination_node_id];if(to)paths.push(`<path class="edge ${i?'branch':''}" d="${edgePath(n,to,i)}"></path><text class="edge-label" x="${(n.x+to.x+220)/2}" y="${(n.y+to.y+100)/2-8}">${esc(r.event)}</text>`)}$('#edges').innerHTML=paths.join('');$('#nodes').innerHTML=project.nodes.map(n=>`<article class="graph-node ${n.id===selectedNodeId?'selected':''} ${n.id===liveNodeId?'live':''}" data-node="${esc(n.id)}" style="left:${n.x}px;top:${n.y}px">${n.id===project.entry_node_id?'<span class="start-badge">START</span>':''}<div class="node-head"><strong>${esc(n.label||n.id)}</strong><span class="node-id">${esc(n.id)}</span></div><div class="node-body">${(n.routes||[]).map(r=>`<div class="node-route"><span class="event-dot"></span>${esc(r.event)} -&gt; ${esc(r.outcome||r.destination_node_id||'unset')}</div>`).join('')||'<span class="muted">No routes</span>'}${(n.routes||[]).some(r=>r.outcome)?'<span class="node-outcome">terminal path</span>':''}</div></article>`).join('');bindNodeDrag()}
