function changed(render=true){if(!project)return;editGeneration++;dirty=true;compiledJson='';rehearsalSteps=[];rehearsalResult=null;runtimeState=null;saveState('Saving...','dirty');clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,650);if(render){renderBeats();renderCanvas();renderInspector()}renderRehearsal();renderJourney()}
