function guidedStepEstimate(){let beats=simpleBeats();if(!beats)return 0;return beats.reduce((count,b)=>count+(b.kind==='wait'?1:Math.max(1,Number(b.repeat_count)||1)),0)}
function selectGuidedScenario(){if(!project||!catalog.scenarios.length)return;let wanted=(simpleBeats()||[]).map(x=>`${simpleKinds[x.kind].event}|${x.target??simpleKinds[x.kind].target??''}`),best=null,bestScore=0;for(let scenario of catalog.scenarios){let offered=(scenario.steps||[]).filter(x=>x.kind==='event').map(x=>`${x.event_name}|${x.target||''}`),score=offered.reduce((n,x,i)=>n+(wanted[i]===x?2:wanted.some(y=>y.split('|')[0]===x.split('|')[0])?1:0),0);if(score>bestScore){best=scenario;bestScore=score}}$('#scenario').value=best?.id||''}
