function renderRehearsal(){let card=$('#rehearsal-result'),badge=$('#rehearsal-badge');if(!project){badge.className='readiness neutral';badge.textContent='No quest';card.className='result-card empty';card.textContent='Choose a quest before rehearsing it.';return}if(!rehearsalResult){badge.className='readiness neutral';badge.textContent='Not run';card.className='result-card empty';card.textContent=rehearsalSteps.length?`${rehearsalSteps.length} player action(s) queued.`:'Rehearse the current quest, or open More rehearsal options.';renderJourney();return}let d=rehearsalResult,finished=!!d.outcome,failed=d.outcome==='fail',limits=d.limitations||[],paths=d.available_paths||[];badge.className=`readiness ${failed?'bad':finished?'good':'warn'}`;badge.textContent=failed?'Fail path':finished?'Complete':'In progress';card.className='result-card';card.innerHTML=`<div class="result-summary"><div><span class="eyebrow">Current beat</span><h3>${esc(stageName(d.current_node_id))}</h3></div><span class="readiness ${failed?'bad':finished?'good':'warn'}">${esc(d.outcome||'In progress')}</span></div>${(d.trace||[]).map((t,index)=>`<div class="trace-row ${t.status}"><strong>${index+1}. ${esc(eventLabel(t.event_name,t.target))}</strong>${t.required_count>1?`<span class="trace-progress">${t.current_count}/${t.required_count}</span>`:''}<br><span class="muted">${esc((t.effects||[]).join(' - ')||t.next_instruction||'The quest is waiting for the current beat.')}</span></div>`).join('')||'<div class="empty">No player actions have been tried yet.</div>'}${limits.length?`<div class="path-note"><strong>Coverage limits</strong><ul>${limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${paths.length?`<small>Available paths: ${esc(paths.join(', '))}</small>`:''}</div>`:''}<p class="disclaimer">${esc(d.disclaimer||'Browser rehearsal does not prove a live Valheim adapter.')}</p>`;renderJourney()}
async function runRehearsal(scenarioId,mode='manual'){if(!project){status('Choose a quest first','Rehearsal needs a saved draft.',true);return}if(!(await saveNow()))return;let sequence=beginOperation('rehearsal'),context=requestContext(),steps=mode==='guided'?[]:clone(rehearsalSteps);if(scenarioId){let s=catalog.scenarios.find(x=>x.id===scenarioId);steps=clone(s?.steps||[])}rehearsalSteps=steps;try{let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/rehearse`,{method:'POST',body:JSON.stringify({mode,path_id:null,scenario_id:scenarioId||null,steps})});if(!isLatestOperation('rehearsal',sequence)||!isCurrentContext(context))return;rehearsalResult=d;liveNodeId=d.current_node_id;if(mode==='guided')rehearsalSteps=clone(d.generated_steps||[]);renderCanvas();renderRehearsal();status('Rehearsal complete',d.outcome?`Preview reached ${d.outcome}.`:`Current beat: ${stageName(d.current_node_id)}.`)}catch(e){if(!isLatestOperation('rehearsal',sequence)||!isCurrentContext(context))return;rehearsalResult=null;$('#rehearsal-badge').className='readiness bad';$('#rehearsal-badge').textContent='Needs attention';$('#rehearsal-result').className='result-card';$('#rehearsal-result').textContent=JSON.stringify(e.diagnostics||e,null,2);renderJourney();status('Rehearsal rejected',e.error||'The quest graph is invalid.',true)}}
async function certify(store=true){if(!project){status('Choose a quest first','There is no draft to check.',true);throw{error:'project_missing'}}if(!(await saveNow()))throw{error:'save_failed'};let sequence=beginOperation('certify'),context=requestContext();try{let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/${store?'certify':'validate'}`,{method:'POST'});if(!isLatestOperation('certify',sequence)||!isCurrentContext(context))throw{error:'stale_request'};compiledJson=d.experience_json||'';$('#json-output').textContent=compiledJson||'Validation passed. Certify to inspect the exact Runtime document.';status(store?'Certified':'Quest check passed',d.content_hash);return{...d,request_context:context}}catch(e){if(!isLatestOperation('certify',sequence)||!isCurrentContext(context))throw{error:'stale_request'};if(e.error==='stale_request'){status('Draft changed','Check the current revision again before using certified output.',true);throw e}status('Quest needs attention',e.error||'Validation failed',true);$('#json-output').textContent=JSON.stringify(e.diagnostics||e,null,2);throw e}}
async function publish(){if(!project||publishPending){if(!project)status('Choose a quest first','There is no draft to publish.',true);return}showStage('publish');setPublishLock(true);try{let certified=await certify(true);if(!(await saveNow()))throw{error:'save_failed'};let context=requestContext();if(!isCurrentContext(context)||context.revision!==certified.request_context.revision)throw{error:'stale_request'};let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/publish`,{method:'POST',body:JSON.stringify({expected_revision:context.revision})});if(!isCurrentContext(context))return;status('Published to Runtime inbox',`${d.receipt.pack_id} ${d.receipt.version} - ${d.receipt.content_hash}`);await refreshRuntime()}catch(e){if(e.status===409&&e.conflict&&e.project){project=e.project;let migrated=normalizeProjectRoutes(project);dirty=migrated;selectedNodeId=project.entry_node_id;selectedRouteId=node()?.routes?.[0]?.id||null;rehearsalResult=null;runtimeState=null;saveState(migrated?'Saving migration...':'Reloaded newer draft',migrated?'dirty':'bad');renderAll();status('Newer draft loaded','Publish stopped because this project changed after certification. Review the newer draft and publish again.',true);if(migrated){editGeneration++;clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,0)}}else if(e.error==='same_version_hash_collision')status('Version already published','Start a new iteration from the project actions menu.',true);else if(e.error==='stale_request')status('Publish paused','The draft changed after certification. Check it again before publishing.',true);else if(e.error)status('Publish rejected',e.error,true)}finally{setPublishLock(false)}}
async function refreshRuntime(){let sequence=beginOperation('runtime');if(!project){runtimeState=null;$('#runtime-phase').className='readiness neutral';$('#runtime-phase').textContent='Waiting for project';$('#runtime-next').textContent='Publish a quest to begin.';$('#runtime-receipts').innerHTML='<div class="empty">No matching live receipts yet.</div>';$('#receipt-count').textContent='None yet - refreshes automatically';$('#runtime-receipt-details').open=false;renderJourney();return}let context=requestContext();try{let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/runtime-status`);if(!isLatestOperation('runtime',sequence)||!isCurrentContext(context))return;runtimeState=d;let phase=d.phase.replaceAll('_',' '),terminal=['complete','fail'].includes(d.phase);$('#runtime-phase').className=`readiness ${!d.available?'bad':terminal?'good':'warn'}`;$('#runtime-phase').textContent=phase;$('#runtime-next').textContent=d.next_instruction;let phases=['published','checked','active','bound','complete'],effective=d.phase==='fail'?'complete':d.phase,at=phases.indexOf(effective);$$('.lap li').forEach((li,i)=>{li.classList.toggle('done',i<at||terminal);li.classList.toggle('current',i===at&&!terminal)});let receipts=d.receipts||[];$('#receipt-count').textContent=receipts.length?`${receipts.length} matching receipt${receipts.length===1?'':'s'} - refreshes automatically`:'None yet - refreshes automatically';if(receipts.length&&!$('#runtime-receipt-details').dataset.seen){$('#runtime-receipt-details').open=true;$('#runtime-receipt-details').dataset.seen='true'}$('#runtime-receipts').innerHTML=receipts.slice(0,12).map(r=>{let stage=r.next_stage_id||r.current_stage_id||r.stage_id||'',count=r.required_count>1?` - ${r.current_count||0}/${r.required_count}`:'';return `<div class="receipt"><strong>${esc(r.operation)} - ${esc(r.status)}</strong><small>${esc(stageName(stage))} ${esc(eventLabel(r.event_name,null))}${count} - ${esc(r.at_utc)}</small></div>`}).join('')||'<div class="empty">No matching live receipts yet.</div>';if(d.current_stage_id){liveNodeId=d.current_stage_id;renderCanvas()}renderJourney()}catch(e){if(!isLatestOperation('runtime',sequence)||!isCurrentContext(context))return;runtimeState={available:false,phase:'unavailable'};$('#runtime-phase').className='readiness bad';$('#runtime-phase').textContent='Unavailable';$('#runtime-next').textContent=e.error||'Runtime state is unavailable on this machine.';renderJourney()}}
function setLibrary(open){$('#library-panel').classList.toggle('open',open);$('#library-scrim').classList.toggle('open',open);$('#library-toggle').setAttribute('aria-expanded',String(open));if(open)requestAnimationFrame(()=>{let heading=$('#library-panel h2');heading.tabIndex=-1;heading.focus()})}
function downloadText(text,name,type='application/json'){let href=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),0)}
function sumNumbers(value){if(typeof value==='number'&&Number.isFinite(value))return value;if(!value||typeof value!=='object')return 0;return Object.values(value).reduce((sum,x)=>sum+sumNumbers(x),0)}
function renderUsage(report){let settings=report.settings_available!==false,aggregate=report.aggregate_available!==false,available=report.available!==false&&settings&&aggregate;$('#usage-enabled').checked=!!report.enabled;$('#usage-enabled').disabled=false;$('#download-usage').disabled=!available;$('#reset-usage').disabled=false;let weeks=Object.keys(report.weeks||{}),observations=sumNumbers(report.weeks||{}),state=available?(report.enabled?'On':'Off'):!settings&&!aggregate?'Settings + counts degraded':!settings?'Settings degraded':'Counts degraded';$('#usage-summary').innerHTML=`<span class="usage-stat"><strong>${state}</strong><span>collection</span></span><span class="usage-stat"><strong>${weeks.length}</strong><span>week${weeks.length===1?'':'s'} retained</span></span><span class="usage-stat"><strong>${observations}</strong><span>aggregate counts</span></span><span class="usage-stat"><strong>${Number(report.retention_weeks)||13}</strong><span>week limit</span></span>`;$('#usage-status').textContent=available?'Stored locally only - no free text or upload capability.':!settings&&!aggregate?'Local preference and aggregate stores are unavailable. Toggle or reset to attempt recovery.':!settings?'The local preference store is unavailable. The toggle remains available to attempt recovery.':'The local aggregate store is unavailable. Reset remains available to attempt recovery.'}
