function bindEnhancements(){
  $('#library-toggle').onclick=()=>setLibrary(!$('#library-panel').classList.contains('open'));$('#library-close').onclick=$('#library-scrim').onclick=()=>setLibrary(false);$('#dismiss-status').onclick=()=>{$('#activity-message').classList.remove('showing','bad')};$('#title').addEventListener('input',()=>{$('#open-project-name').textContent=project?`${project.title} - ${project.version}`:'Turn an idea into a playable quest.'});
  $('#beat-list').addEventListener('keydown',e=>{let card=e.target.closest('[data-beat]');if(!card)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click()}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();let cards=$$('#beat-list [data-beat]'),at=cards.indexOf(card),next=cards[Math.max(0,Math.min(cards.length-1,at+(e.key==='ArrowDown'?1:-1)))];next?.focus()}});$('#beat-browse').onclick=()=>openEventPicker('replace');$('#beat-add-effect').onclick=addBeatEffect;
  $('#beat-specific').addEventListener('change',e=>{if(e.target.matches('[data-beat-target]'))updateBeat(b=>b.target=e.target.value||null);else if(e.target.matches('[data-beat-where]')){let field=e.target.dataset.beatWhere;updateBeat(b=>{b.where||={};let value=e.target.type==='checkbox'?(e.target.checked?'true':null):(e.target.value.trim()||null);if(value==null)delete b.where[field];else b.where[field]=String(value)})}});
  $('#beat-effect-list').addEventListener('click',e=>{let button=e.target.closest('.remove-beat-effect');if(!button)return;let index=Number(button.closest('[data-beat-action]').dataset.beatAction);updateBeat(b=>b.actions.splice(index,1))});$('#beat-effect-list').addEventListener('change',e=>{let card=e.target.closest('[data-beat-action]'),field=e.target.dataset.beatActionField;if(!card||!field)return;let index=Number(card.dataset.beatAction);updateBeat(b=>{let action=b.actions[index];action[field]=e.target.type==='number'?Number(e.target.value):e.target.value;if(field==='kind'){let defs=actionDefinition('spawn').prefabs||{};action.prefab=(defs[action.kind]||[])[0]||''}})});
  $('#event-picker-close').onclick=()=>$('#event-picker').close();$('#event-search').oninput=renderEventPicker;$('#include-extended').onchange=renderEventPicker;$('#event-categories').onclick=e=>{let button=e.target.closest('[data-event-category]');if(!button)return;pickerCategory=button.dataset.eventCategory;renderEventPicker()};$('#event-results').onclick=e=>{let row=e.target.closest('[data-picker-event]');if(!row)return;pickerSelection=row.dataset.pickerEvent;renderEventPicker()};$('#event-results').ondblclick=e=>{let row=e.target.closest('[data-picker-event]');if(row)choosePickerEvent(row.dataset.pickerEvent)};$('#event-results').onkeydown=e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;let rows=$$('#event-results .event-row'),at=rows.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?rows.length-1:Math.max(0,Math.min(rows.length-1,at+(e.key==='ArrowDown'?1:-1)));e.preventDefault();rows[next]?.focus();rows[next]?.click()};$('#event-preview').onclick=e=>{let button=e.target.closest('[data-picker-choose]');if(button)choosePickerEvent(button.dataset.pickerChoose)};$('#event-search').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();$('#event-results .event-row')?.focus()}};
  $('#route-where-fields').addEventListener('change',e=>{let field=e.target.dataset.routeWhere;if(!field)return;let value=e.target.type==='checkbox'?(e.target.checked?'true':null):(e.target.value.trim()||null);setRouteWhere(field,value,false)});
  $('#include-live-evidence').onchange=e=>{$('#live-evidence-warning').hidden=!e.target.checked};$('#download-bundle').onclick=downloadBundle;$('#download-questpack').onclick=downloadQuestpack;$('#download-compiled').onclick=downloadCompiledJson;$('#refresh-history').onclick=loadHistory;$('#usage-enabled').onchange=e=>setUsageEnabled(e.target.checked);$('#download-usage').onclick=async()=>{try{let name=await downloadPost('/api/v2/quest-studio/usage/export',{},'quest-studio-usage.json');status('Usage aggregate downloaded',name)}catch(e){status('Usage export unavailable',e.error||String(e),true)}};$('#reset-usage').onclick=resetUsage;
}
boot().catch(e=>status('Studio unavailable',e.error||String(e),true));
""";
}
